#!/usr/bin/env python3
"""Extract the actual DCN201 HUBP1 pitch and pixel-format preparation."""
import argparse
import hashlib
import re
from extract_scaler_geometry import ROOT, REF, COMMIT, extract

OUT = ROOT / 'driver/shim/generated/dc_surface_layout.inc'

def generate():
    pieces = ['/* SPDX-License-Identifier: MIT */',
              '/* Generated by tools/import/extract_surface_layout.py. Do not edit.\n'
              f' * PROVENANCE: Linux amdgpu DC, MIT, {COMMIT}. */']
    for name in ('hdmi-link/dc_hw_types.h', 'dcn10_hubp.c'):
        raw = (REF / name).read_bytes()
        text = raw.decode().replace('\r\n', '\n')
        pieces += [text[:text.index('*/') + 2],
                   f'/* {name}, sha256 {hashlib.sha256(raw).hexdigest()} */']
        if name.endswith('.h'):
            for decl in ('enum surface_pixel_format', 'struct rect', 'struct plane_size', 'struct dc_plane_dcc_param'):
                matches = re.findall(r'^' + decl + r' \{.*?^\};', text, re.M | re.S)
                if len(matches) != 1:
                    raise ValueError(decl)
                pieces.append(matches[0])
        else:
            for name in ('hubp1_program_size', 'hubp1_program_pixel_format'):
                function = extract(text, name)
                # Private linkage declaration; the following definition is verbatim.
                pieces += ['/* Adapter linkage declaration. */\nstatic ' + function[:function.index('\n{')] + ';', function]
    return ('\n\n'.join(pieces).rstrip() + '\n').encode()

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generate()
    if args.check:
        if OUT.read_bytes() != expected:
            raise SystemExit('Surface layout extraction mismatch')
    else:
        OUT.write_bytes(expected)
    print('Surface layout extraction OK')
